def solve(grid):
    rows = len(grid)
    cols = len(grid[0])

    visited = [[False]*cols for _ in range(rows)]
    result = [row[:] for row in grid]

    from collections import deque, defaultdict

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 7 and not visited[r][c]:
                comp = []
                q = deque([(r, c)])
                visited[r][c] = True
                count_8 = 0
                while q:
                    cr, cc = q.popleft()
                    comp.append((cr, cc))
                    if grid[cr][cc] == 8:
                        count_8 += 1
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0<=nr<rows and 0<=nc<cols and not visited[nr][nc] and grid[nr][nc] != 7:
                            visited[nr][nc] = True
                            q.append((nr, nc))

                comp_set = set(comp)
                max_row = max(cr for cr, cc in comp)

                dist = {}
                q = deque()
                for cr, cc in comp:
                    if cr == max_row:
                        dist[(cr, cc)] = 0
                        q.append((cr, cc))

                while q:
                    cr, cc = q.popleft()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if (nr, nc) in comp_set and (nr, nc) not in dist:
                            dist[(nr, nc)] = dist[(cr, cc)] + 1
                            q.append((nr, nc))

                groups = defaultdict(list)
                for cell, d in dist.items():
                    groups[d].append(cell)

                fill_order = []
                for d in sorted(groups.keys()):
                    cells = groups[d]
                    center_col = sum(cc for cr, cc in cells) / len(cells)
                    cells.sort(key=lambda x: (-x[0], abs(x[1] - center_col), x[1]))
                    fill_order.extend(cells)

                for i, (cr, cc) in enumerate(fill_order):
                    result[cr][cc] = 8 if i < count_8 else 0

    return result
